records.cmd:
$ErrorActionPreference = 'Stop'
$probe = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe'
if (Test-Path -LiteralPath $probe) { & $probe -all -products '*' -format json -utf8; Write-Output ('VSWHERE_EXIT=' + $LASTEXITCODE); & $probe -all -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath; Write-Output ('CPP_PROBE_EXIT=' + $LASTEXITCODE) } else { Write-Output 'VSWHERE_NOT_FOUND' }
$kits = 'HKLM:\SOFTWARE\Microsoft\Windows Kits\Installed Roots'
if (Test-Path -LiteralPath $kits) { Get-ItemProperty -LiteralPath $kits | Select-Object KitsRoot10 }
$sdkRoot = Join-Path ${env:ProgramFiles(x86)} 'Windows Kits\10'
if (Test-Path -LiteralPath $sdkRoot) { Get-ChildItem -LiteralPath (Join-Path $sdkRoot 'Include') -ErrorAction SilentlyContinue | Select-Object Name; Get-ChildItem -LiteralPath (Join-Path $sdkRoot 'Lib') -ErrorAction SilentlyContinue | Select-Object Name } else { Write-Output 'WINDOWS_SDK_ROOT_NOT_FOUND' }
$edgeRoots = @('HKLM:\SOFTWARE\WOW6432Node\Microsoft\EdgeUpdate\Clients','HKLM:\SOFTWARE\Microsoft\EdgeUpdate\Clients','HKCU:\SOFTWARE\Microsoft\EdgeUpdate\Clients')
foreach ($edgeRoot in $edgeRoots) { if (Test-Path -LiteralPath $edgeRoot) { Get-ChildItem -LiteralPath $edgeRoot | ForEach-Object { Get-ItemProperty -LiteralPath $_.PSPath } | Where-Object { $_.name -like '*WebView2*' } | Select-Object name,pv } }
rustc -vV
Write-Output ('RUSTC_EXIT=' + $LASTEXITCODE)
cargo --version
Write-Output ('CARGO_EXIT=' + $LASTEXITCODE)

